<template>
  <section class="hvg-integrated-section stack-lg" :data-research-section="section" aria-label="Research results for this section">
    <div class="card">
      <div class="section-header compact"><div><h3>{{headings[section]}}</h3><p class="muted">{{descriptions[section]}}</p></div></div>
      <details class="hvg-evidence-note"><summary>How to interpret this evidence</summary><p>Feature and gene-set q values describe group associations, not gene-level significance. Technical resampling is not independent biological validation. Sequence composition does not measure cellular resource consumption.</p></details>
      <template v-if="section==='overview'">
        <div class="table-wrap"><table class="table compact-table"><thead><tr><th>Context</th><th>Eligible genes</th><th>HVG</th><th>non-HVG</th><th>Annotation coverage</th><th>Core audited / tested</th></tr></thead><tbody><tr v-for="c in contextCoverage" :key="c.context_id"><td>{{c.context_id}}</td><td>{{c.U}}</td><td>{{c.H}}</td><td>{{c.N}}</td><td>{{c.annotated_genes}} / {{c.U}} ({{(100*c.annotation_fraction).toFixed(2)}}%)</td><td>{{c.audited_core}} / {{c.tested_core}}</td></tr></tbody></table></div>
        <ul v-if="state.summary.limitations?.length"><li v-for="v in state.summary.limitations" :key="v">{{v}}</li></ul>
        <details><summary>Stage status and timing</summary><div class="table-wrap"><table class="table compact-table"><thead><tr><th>Stage</th><th>Execution status</th><th>Scientific status</th><th>Seconds</th><th>Reason</th></tr></thead><tbody><tr v-for="(v,k) in state.summary.stages" :key="k"><td>{{k}}</td><td>{{v.execution_status}}</td><td>{{v.scientific_status}}</td><td>{{formatValue(v.seconds)}}</td><td>{{v.reason}}</td></tr></tbody></table></div></details>
        <h4>Supported observations</h4><p v-if="!observations.length" class="muted">No observations meet the declared thresholds in this context. Full results and reasons for non-estimable tests remain available.</p><ul><li v-for="p in observations.slice(0,12)" :key="p.phenomenon_id"><button class="hvg-evidence-link" @click="navigateObservation(p)">{{p.feature_key || p.term_name || p.term_key}}</button>: {{observationText(p.observation)}}; Effect {{formatValue(p.effect)}}; Global q {{formatValue(p.q_global)}}; {{fieldLabel(p.support_level)}}.</li></ul>
      </template>
      <details v-if="section==='input_qc' || section==='phase1'" class="hvg-method-details"><summary>Official HVG method and annotation release</summary><p class="muted">Annotation release: {{state.summary.presentation?.annotation_snapshot_id || 'Not recorded'}}</p><dl><template v-for="(value,key) in state.summary.presentation?.methods?.[state.context] || {}" :key="key"><dt>{{fieldLabel(key)}}</dt><dd>{{formatValue(value)}}</dd></template></dl></details>
      <p v-if="!isUnified && section==='context_patterns' && (state.summary.contexts?.length||0)<2" class="muted">Only the global context was declared. No between-context comparison is available; library suffixes are not treated as independent donors.</p>
      <div v-if="!['overview','downloads'].includes(section)" class="row hvg-result-filters">
        <label>Feature<input class="input" v-model="draft.feature" placeholder="e.g. genome::gc3_percent" @keyup.enter="apply" /></label>
        <label>Function ID<input class="input" v-model="draft.term" placeholder="e.g. GO_BP::GO:0006351" @keyup.enter="apply" /></label>
        <label>Annotation source<select class="input" v-model="draft.source"><option value="">All sources</option><option v-for="s in sources" :key="s">{{s}}</option></select></label>
        <label>Direction<select class="input" v-model="draft.direction"><option value="">All</option><option value="high">high</option><option value="low">low</option></select></label>
        <label>Analysis scope<select class="input" v-model="draft.scope"><option value="all_annotated">All annotated genes</option><option value="hvg_annotated">Within HVGs</option></select></label>
        <label>Maximum global q<input class="input" v-model="draft.qmax" type="number" min="0" max="1" step="0.01" placeholder="All" /></label>
        <button class="btn" @click="apply">Apply filters</button><button class="btn secondary" @click="clear">Clear filters</button>
      </div>
    </div>
    <section v-if="isUnified && section==='context_patterns'" class="card" data-unified-modes>
      <h3>Original metadata analysis modes</h3><p class="muted">Every available group, condition, timecourse, sample-consensus and trajectory mode runs in this task. Original pattern and consensus rules are preserved; subset labels use the same official HVG method. Unavailable metadata and failed subsets remain explicit in the tables below. These exploratory patterns do not replace the global research baseline.</p>
    </section>
    <section v-if="isUnified && section==='group_comparison'" class="stack-lg" data-original-comparison>
      <div class="card"><h3>Original multi-omics comparison</h3><p class="muted">Calculated in this run from the same global standard HVG labels. Original v2 statistics and correction remain separate from the extended research tests below. Download the complete original outputs in Downloads.</p><p v-if="comparisonBusy">Loading original comparison…</p><p v-if="comparisonError" role="alert">{{comparisonError}}</p></div>
      <HvgGroupComparisonPanel v-if="originalComparison" :identifier="identifier" :embedded-comparison="originalComparison" :visual-params="{analysis_run_id:state.run,context_id:state.context}" />
    </section>
    <ResearchCharts v-if="definition.plots?.length" :section="section" :identifier="identifier" :state="state" :kinds="definition.plots" @table="selectTable" @inspect="inspect" />
    <ResearchOptionalModel v-if="!isUnified && ['phase2','model_evidence'].includes(section)" :state="state" :section="section" @inspect="inspect" />
    <div v-if="section==='genes'" class="card">
      <div class="section-header compact"><div><h3>Gene evidence lookup</h3><p class="muted">Look up any gene in the current universe, including genes with feature evidence but no functional annotation.</p></div></div>
      <form class="row" @submit.prevent="openGene(state.gene)"><input class="input" v-model="state.gene" placeholder="Enter a gene ID" aria-label="Gene ID" /><button class="btn" :disabled="detailBusy">View gene evidence</button></form>
    </div>
    <div v-if="section==='downloads'" class="card">
      <h3>Results and reproducibility files</h3><p class="muted">Download complete tables and gene sets below. Each interactive chart also exports PNG, SVG, CSV and TSV. Saved reports and static figures retain their original run provenance.</p>
      <input class="input" v-model="artifactQuery" placeholder="Filter by file path, name or format" aria-label="Filter download files" />
      <p v-if="artifactError" role="alert">{{artifactError}} <button class="btn secondary" @click="loadArtifacts">Reload file list</button></p>
      <div class="table-wrap"><table class="table compact-table"><thead><tr><th>File</th><th>Bytes</th><th>SHA256</th><th>Action</th></tr></thead><tbody><tr v-for="a in visibleArtifacts" :key="a.artifact_id"><td>{{artifactLabel(a.relative_path || a.name)}}</td><td>{{a.bytes?.toLocaleString('en-US')}}</td><td class="hvg-hash">{{a.sha256}}</td><td><button class="btn secondary" @click="download(a)">Download</button></td></tr></tbody></table></div>
    </div>
    <div v-if="definition.tables?.length" class="card hvg-research-table">
      <div class="section-header compact"><div><h3>Statistical details</h3><p class="muted">Charts use their declared saved evidence independently of table pagination. Original input/model diagnostics retain their own scope. Missing estimates remain blank; inspect status and reason for details.</p></div></div>
      <div class="row hvg-result-filters"><label>Result table<select class="input" v-model="table"><option v-for="t in availableTables" :key="t" :value="t">{{tableLabels[t] || t}}</option></select></label><label>Search<input class="input" v-model="query" placeholder="Gene, feature or function" @keyup.enter="refreshTable" /></label><label v-if="table==='original_model_scores'">Prediction class<input class="input" v-model="state.modelClass" placeholder="All saved classes" @keyup.enter="refreshTable" /></label><label v-if="table==='candidates'">Tier<select class="input" v-model="tier"><option value="">All</option><option>A</option><option>B</option><option>C</option><option>D</option></select></label><button class="btn secondary" @click="refreshTable">Search table</button><button class="btn secondary" @click="exportTable">Export all filtered rows (CSV)</button></div>
      <p v-if="tableBusy" role="status">Loading statistical results…</p><p v-if="tableError" role="alert">{{tableError}} <button class="btn secondary" @click="loadTable">Retry</button></p>
      <p class="muted">{{total.toLocaleString('en-US')}} matching rows · Page {{page}} / {{Math.max(1,Math.ceil(total/pageSize))}}</p>
      <div class="table-wrap"><table class="table compact-table"><thead><tr><th v-for="c in columns" :key="c"><button class="hvg-column-sort" :disabled="!sortable.includes(c)" @click="sortTable(c)">{{fieldLabel(c)}}{{sort===c?(order==='asc'?' ↑':' ↓'):''}}</button></th><th>Inspect</th></tr></thead><tbody><tr v-for="(r,i) in rows" :key="i"><td v-for="c in columns" :key="c">{{formatValue(r[c])}}</td><td><div class="hvg-row-actions"><button v-if="r.feature_key" @click="openFeature(r.feature_key)">Feature</button><button v-if="r.set_id" @click="openSet(r.set_id)">Members</button><button v-if="r.term_key" @click="openTerm(r.term_key)">Function</button><button v-if="table==='gsea' && r.run_id" @click="openCurve(r)">GSEA curve</button><button v-if="r.gene_id" @click="openGene(r.gene_id)">Gene</button></div></td></tr></tbody></table></div>
      <p v-if="!tableBusy && !rows.length" class="muted">No rows match these filters. Clear the q filter to include non-estimable tests and their reasons. An empty selection does not imply a failed analysis.</p>
      <div class="row"><button class="btn secondary" :disabled="page<=1||tableBusy" @click="page--;loadTable()">Previous</button><button class="btn secondary" :disabled="page*pageSize>=total||tableBusy" @click="page++;loadTable()">Next</button><label>Rows per page <select v-model.number="pageSize" @change="refreshTable"><option :value="25">25</option><option :value="50">50</option><option :value="100">100</option><option :value="200">200</option></select></label></div>
    </div>
    <div v-if="detailBusy || detail || detailError" class="card hvg-research-detail" aria-live="polite">
      <div class="section-header compact"><h3>{{detailTitle || 'Evidence details'}}</h3><button class="btn secondary" @click="closeDetail">Close details</button></div>
      <p v-if="detailBusy" role="status">Loading complete evidence…</p><p v-if="detailError" role="alert">{{detailError}}</p>
      <template v-if="detail">
        <p class="muted">Evidence uses the selected run and context. Feature, function and set-level q values are not independent p values for individual genes.</p>
        <button class="btn secondary" @click="downloadDetail">Download complete evidence (JSON)</button>
        <WorkflowChart slot-id="hvg.detail.gsea" v-if="workflowVisualsEnabled && detailCurveSelection" resource="hvg" :identifier="identifier" chart-id="H16" :params="state.params(detailCurveSelection,false)" :height="400" />
        <EChart v-else-if="detailCurve" :option="detailCurve" :data-rows="detailCurveRows" :auto-loading="false" caption="Reconstructed from saved gene ranks and members. The preview samples up to 1,000 regular positions and retains the peak. Full ranks and members are downloadable." />
        <WorkflowChart slot-id="hvg.detail.feature" v-if="workflowVisualsEnabled && detailFeature && detailDistribution" resource="hvg" :identifier="identifier" chart-id="H10" :params="state.params({feature_key:detailFeature},false)" :height="400" />
        <EChart v-else-if="detailDistribution" :option="detailDistribution" :data-rows="detail.distribution || []" :auto-loading="false" caption="Quantiles use a shared reference and scale for HVGs and non-HVGs." />
        <WorkflowChart slot-id="hvg.detail.gene" v-if="workflowVisualsEnabled && detail?.core_feature_values" resource="hvg" :identifier="identifier" chart-id="H23" :params="state.params({gene_id:state.gene},false)" :height="550" />
        <EChart v-else-if="geneProfile" :option="geneProfile" :height="550" :data-rows="detail.core_feature_values" :auto-loading="false" caption="Up to 48 features with the largest deviation from the non-HVG reference median. Scroll the plot to explore; complete Core values, units and exclusions are available below and in JSON. Percentiles are not gene-level significance." />
        <template v-for="(v,k) in detail" :key="k"><details v-if="Array.isArray(v)"><summary @click="expanded[k]=!expanded[k]">{{fieldLabel(k)}} ({{v.length}} total; preview up to 50 rows)</summary><div v-if="expanded[k]" class="table-wrap"><table v-if="v.length" class="table compact-table"><thead><tr><th v-for="c in Object.keys(v[0] || {})" :key="c">{{fieldLabel(c)}}</th></tr></thead><tbody><tr v-for="(r,i) in v.slice(0,50)" :key="i"><td v-for="c in Object.keys(v[0] || {})" :key="c">{{formatValue(r[c])}}</td></tr></tbody></table><p v-else>No evidence of this type is available.</p></div></details></template>
      </template>
    </div>
  </section>
</template>
<script setup>
import {computed,reactive,ref,watch,onBeforeUnmount} from 'vue'
import EChart from '../EChart.vue'
import WorkflowChart from '../workflow/WorkflowChart.vue'
import {workflowVisualsEnabled} from '../../api/workflowVisuals'
import ResearchCharts from './ResearchCharts.vue'
import ResearchOptionalModel from './ResearchOptionalModel.vue'
import HvgGroupComparisonPanel from '../HvgGroupComparisonPanel.vue'
import {researchDownload,researchSafeExport} from '../../api/hvgResearch'
import {formatValue,researchOption,curveOption,geneProfileOption,fieldLabel,presentationText} from './researchCharts'
const props=defineProps({state:{type:Object,required:true},section:{type:String,required:true},identifier:{type:String,required:true}}),emit=defineEmits(['navigate'])

const isUnified=computed(()=>props.state.summary.model_policy==='removed')
const originalComparison=ref(null),comparisonBusy=ref(false),comparisonError=ref('')
let comparisonGeneration=0
watch(()=>[props.section,props.state.run,props.state.context,props.state.version,isUnified.value],async()=>{
 const id=++comparisonGeneration;originalComparison.value=null;comparisonError.value='';comparisonBusy.value=false
 if(!isUnified.value||props.section!=='group_comparison')return
 comparisonBusy.value=true
 try{const result=await props.state.get('original-comparison',{},false);if(id===comparisonGeneration)originalComparison.value=result}
 catch(e){if(id===comparisonGeneration)comparisonError.value=e.response?.data?.error?.message||e.message}
 finally{if(id===comparisonGeneration)comparisonBusy.value=false}
},{immediate:true})
const observationText=presentationText
const artifactLabel=text=>String(text||'').replace('结果总览.html','results_overview.html')

const sources=['GO_BP','GO_MF','GO_CC','KEGG_pathway','KEGG_module']
const headings={overview:'Study design and findings',input_qc:'Input, mapping and Core audit',phase1:'Standard HVG results',context_patterns:'Metadata modes and research contexts',group_comparison:'Stoichiometric differences: HVG vs non-HVG',phase2:'Feature and function associations',model_evidence:'Evidence and stability',downstream:'Functions and candidate genes',genes:'Gene evidence',downloads:'Research files'}
const descriptions={overview:'Results are scoped to the selected run, context and platform annotation release.',input_qc:'Every registered Core field is audited, including redundant fields, metadata, exclusions and missingness.',phase1:'Labels come directly from the standard algorithm and remain fixed throughout stoichiometric analysis.',context_patterns:'Original metadata modes and explicitly declared research contexts are reported separately. Overlapping gene universes are not independent replicates.',group_comparison:'Explore raw effects, covariate adjustment, matching and directional gene sets separately. Features with different units are not summed.',phase2:'Explore GO functions, locations and KEGG pathways. GSEA uses actual feature ranks, separately from legacy candidate-score ranks.',model_evidence:'Parameter and cell resampling assess technical sensitivity. Predictive model analysis is excluded from the unified workflow.',downstream:'Compare baseline, feature-subset and within-HVG enrichment. A smaller q value alone is not a test of stronger enrichment.',genes:'Inspect sequence features, functional context and candidate evidence without treating group statistics as gene-level significance.',downloads:'Trace original values, complete gene sets, analysis universes and reproducibility metadata.'}
const tableLabels={workflow_modes:'Metadata mode execution status',workflow_subsets:'Subset HVG summaries',workflow_patterns:'Original pattern and consensus results',workflow_members:'Subset HVG gene labels',candidate_ora:'Research candidate functional enrichment',network_status:'Network data availability',features:'Feature evidence summary',feature_tests:'Raw feature tests',core_audit:'Complete Core audit',adjusted:'Covariate adjustment',matching:'Matching sensitivity',categorical_tests:'Categorical features',sets:'Directional gene sets',set_members:'Complete set members',gene_features:'Gene selection evidence',adjusted_sets:'Residual-adjusted sets',joint_sets:'Joint feature sets',baseline:'Baseline HVG enrichment',matched_baseline:'HVG enrichment in matched eligible universes',subset:'Directional subset enrichment',within_hvg:'Within-HVG enrichment',enrichment_comparison:'Enrichment in a shared universe',supplementary_ora:'Residual and joint-set enrichment',within_pathways:'Raw within-function comparisons',within_adjusted:'Adjusted within-function comparisons',feature_pathways:'Continuous feature–function associations',gsea:'Feature-ranked GSEA',gsea_runs:'GSEA eligibility',interactions:'Feature × function interactions',ranked_genes:'Complete saved gene ranks',leading_edge:'Complete leading edge',replication:'Official HVG technical reruns',feature_stability:'Feature stability',candidate_stability:'Technical gene selection frequency',set_stability:'Gene-set stability',candidates:'Candidate genes',candidate_evidence:'Candidate evidence',gene_pathways:'Candidate–function associations',labels:'All standard HVG labels',annotations:'Run-specific annotations',eligibility:'Input gene eligibility',redundancy:'Redundancy handling',universes:'Analysis universes',hypotheses:'Complete hypothesis registry'}
Object.assign(tableLabels,{mapping:'Gene ID mapping by omics',feature_provenance:'Feature provenance and release',feature_sensitivity:'Feature evidence per sensitivity run',threshold_sensitivity:'Directional threshold sensitivity',baseline_stability:'Enrichment per technical resample',replication_labels:'Official labels per technical rerun'})
Object.assign(tableLabels,{original_method_status:'Original backend and method status',original_input_qc:'Input validation record',original_metadata:'Metadata validation record',original_model_comparison:'Saved prediction model comparison',original_bootstrap:'Saved model bootstrap stability',original_model_scores:'Prediction signals and residuals',original_model_associations:'Prediction-branch feature associations',original_negative_controls:'Negative controls and permutations',original_evidence:'Prediction evidence assessment',original_candidate_components:'Original candidate score components',original_candidate_ora:'Candidate-score ORA terms',original_candidate_ora_full:'Complete candidate-score ORA',original_candidate_gsea:'Candidate-score prerank GSEA',original_ppi:'PPI modules and skipped reasons',original_enrichment_summary:'Candidate enrichment coverage and methods'})
const definition=computed(()=>props.state.summary.presentation?.sections?.[props.section]||{plots:[],tables:[]})
const contextCoverage=computed(()=>(props.state.summary.coverage||[]).filter(c=>c.context_id===props.state.context))
const observations=computed(()=>props.state.phenomena.filter(p=>!p.context_id||p.context_id===props.state.context))
const draft=reactive({feature:'',term:'',source:'',direction:'',scope:'all_annotated',qmax:''})
watch(()=>[props.state.feature,props.state.term,props.state.source,props.state.direction,props.state.scope,props.state.qmax],()=>Object.keys(draft).forEach(k=>draft[k]=props.state[k]),{immediate:true})
function apply(){if(draft.qmax!==''&&(!Number.isFinite(Number(draft.qmax))||Number(draft.qmax)<0||Number(draft.qmax)>1)){tableError.value='q must be a number between 0 and 1.';return}Object.assign(props.state,draft);props.state.version++;props.state.persist()}
function clear(){props.state.clear();query.value='';tier.value='';props.state.set=''}
const table=ref(''),query=ref(''),tier=ref(''),rows=ref([]),total=ref(0),page=ref(1),pageSize=ref(50),sort=ref(''),order=ref('asc'),tableBusy=ref(false),tableError=ref(''),artifacts=ref([]),artifactQuery=ref(''),artifactError=ref('')
const detailCurveSelection=ref(null)
const detailFeature=ref(null)
const detail=ref(null),detailTitle=ref(''),detailBusy=ref(false),detailError=ref(''),detailCurve=ref(null),detailCurveRows=ref([]),expanded=reactive({})
const sortable=['feature_key','gene_id','gene_name','term_key','term_name','q_global','effect','beta','priority_rank','hvg_score','n_members','source','final_status','omics','family','status','nes','fold_enrichment','context_id','priority_tier','n1','n0','rank','hvg_rank','direction']
const columns=computed(()=>{const present=[...new Set(rows.value.flatMap(Object.keys))],first=['gene_id','gene_name','feature_key','term_key','term_name','direction','scope','source','priority_tier','priority_rank','status','n1','n0','N','K','n','k','effect','ci_low','ci_high','beta','nes','fold_enrichment','p_value','q_global'];return first.filter(k=>present.includes(k)).concat(present.filter(k=>!first.includes(k)))})
const availableTables=computed(()=>[...new Set([...(definition.value.tables||[]),...(table.value?[table.value]:[])])])
let generation=0,detailGeneration=0,controller
const tableParams=()=>({stoich_class:table.value==='original_model_scores'?props.state.modelClass||undefined:undefined,page:page.value,page_size:pageSize.value,query:query.value,priority_tier:tier.value||undefined,sort:sort.value||undefined,order:order.value,scope:['feature_pathways','gsea','gsea_runs','ranked_genes','leading_edge'].includes(table.value)?props.state.scope||undefined:undefined,set_id:table.value==='set_members'?props.state.set||undefined:undefined})
async function loadTable(){if(!table.value)return;const id=++generation;controller?.abort();controller=new AbortController();tableBusy.value=true;tableError.value='';rows.value=[];try{const p=await props.state.get('table/'+table.value,tableParams(),!table.value.startsWith('original_'),controller.signal);if(id===generation){rows.value=p.rows||[];total.value=p.total||0}}catch(e){if(id===generation&&e.code!=='ERR_CANCELED')tableError.value=e.response?.data?.error?.message||e.message}finally{if(id===generation)tableBusy.value=false}}
function refreshTable(){page.value=1;loadTable()}
function selectTable(t){if(table.value===t)refreshTable();else table.value=t}
function sortTable(c){order.value=sort.value===c&&order.value==='asc'?'desc':'asc';sort.value=c;refreshTable()}
async function loadArtifacts(){artifactError.value='';try{const p=await props.state.get('artifacts',{},false);artifacts.value=p.rows||[]}catch(e){artifactError.value=e.message}}
const visibleArtifacts=computed(()=>artifacts.value.filter(a=>(a.relative_path+' '+a.name+' '+a.format).toLowerCase().includes(artifactQuery.value.toLowerCase())))
async function download(a){try{await researchDownload(props.identifier,a,props.state.params({},false))}catch(e){artifactError.value=e.message}}
async function exportTable(){try{await researchSafeExport(props.identifier,table.value,props.state.params(tableParams(),!table.value.startsWith('original_')))}catch(e){tableError.value=e.message}}
function closeDetail(){detailFeature.value=null;detailCurveSelection.value=null;detailGeneration++;detail.value=null;detailCurve.value=null;detailCurveRows.value=[];detailError.value='';detailBusy.value=false}
async function fetchDetail(title,endpoint,extra={}){const id=++detailGeneration;detail.value=null;detailCurveSelection.value=null;detailCurve.value=null;detailTitle.value=title;detailError.value='';detailBusy.value=true;try{const r=await props.state.get(endpoint,extra,false);if(id===detailGeneration)detail.value=r;return id===detailGeneration?r:null}catch(e){if(id===detailGeneration)detailError.value=e.response?.data?.error?.message||e.message}finally{if(id===detailGeneration)detailBusy.value=false}}
async function openFeature(key){const saved=await fetchDetail(key,'features/'+encodeURIComponent(key),{feature_key:key});if(saved)detailFeature.value=key}
async function openGene(g){if(!g)return;props.state.gene=g;props.state.persist();await fetchDetail(g,'genes/'+encodeURIComponent(g))}
function openSet(id){props.state.set=id;table.value='set_members';query.value='';refreshTable();return fetchDetail('Set'+id,'gene-sets/'+encodeURIComponent(id),{set_id:id,page:1,page_size:200})}
function openTerm(t){props.state.term=t;props.state.feature='';props.state.set='';emit('navigate','downstream')}
async function openCurve(row){if(workflowVisualsEnabled){detailCurveSelection.value={run_id:row.run_id,term_key:row.term_key,source:row.source,scope:row.scope,feature_key:row.feature_key};detail.value={test:[row]};detailTitle.value='GSEA: '+(row.term_name||row.term_key);return}const r=await fetchDetail('GSEA: '+(row.term_name||row.term_key),'plots/gsea_curve',{run_id:row.run_id,term_key:row.term_key});if(r){detail.value={test:[row],curve_metadata:[{total_ranked_genes:r.total_ranked_genes,method:r.method}]};detailCurveRows.value=r.rows||[];detailCurve.value=r.rows?.length?curveOption(r,props.state.compact):null}}
function inspect({kind,row}){if(kind==='original_classes'&&row.stoich_class){props.state.modelClass=row.stoich_class;emit('navigate','genes');return}if(kind==='gsea'&&row.run_id)return openCurve(row);if(row.gene_id)return openGene(row.gene_id);if(row.feature_key)return openFeature(row.feature_key);if(row.term_key)return openTerm(row.term_key)}
function navigateObservation(p){if(p.feature_key){props.state.feature=p.feature_key;emit('navigate','group_comparison')}else if(p.term_key)openTerm(p.term_key)}
const geneProfile=computed(()=>detail.value?.core_feature_values?.some(r=>typeof r.nonhvg_reference_percentile==='number')?geneProfileOption(detail.value.core_feature_values,props.state.compact):null)
const detailDistribution=computed(()=>{const f=detail.value?.distribution;if(!f?.length)return null;return researchOption({chart_type:'boxplot',rows:f.map(r=>({group:r.group,n:r.n,q05:r.quantiles?.[1],q25:r.quantiles?.[2],median:r.quantiles?.[3],q75:r.quantiles?.[4],q95:r.quantiles?.[5]}))},props.state.compact)})
function downloadDetail(){const blob=new Blob([JSON.stringify(detail.value,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=detailTitle.value.replace(/[^A-Za-z0-9_.-]/g,'_')+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
watch(()=>props.section,()=>{closeDetail();query.value='';sort.value='';tier.value='';page.value=1;table.value=props.section==='genes'&&props.state.modelClass?'original_model_scores':definition.value.tables?.[0]||'';if(props.section==='downloads')loadArtifacts();if(props.section==='genes'&&props.state.gene)openGene(props.state.gene)},{immediate:true})
watch(table,()=>{sort.value='';refreshTable()},{immediate:true})
watch(()=>[props.state.run,props.state.context,props.state.version],()=>{closeDetail();if(props.section==='downloads')loadArtifacts();else refreshTable()})
onBeforeUnmount(()=>{comparisonGeneration++;generation++;detailGeneration++;controller?.abort()})
</script>
